    'conf/projects.json': {
      projects: {
        raf: { path: '/qa/workspace', profile: 'raf', branchPaths: { develop: '/qa/workspace', hotfix: '/qa/hotfix' } },
        etchly: { path: '/qa/etchly', profile: 'product', branchPaths: { develop: '/qa/etchly' } },
