    if (!shape(row, field, ['change', 'item', 'scenario', 'requirement', 'fixed', 'evidence', 'reason', 'regression', 'commits', 'mainHotfix'], ['change', 'item', 'scenario', 'requirement', 'fixed', 'evidence'])) continue;
