import { createHash } from 'node:crypto';
import { isAbsolute, normalize, relative, resolve, sep } from 'node:path';
import { StringDecoder } from 'node:string_decoder';
import { types } from 'node:util';
export type DiagnosticTestId = { file: string; name: string };
export type DiagnosticLocation = { file: string; line: number | null; column: number | null };
export type DiagnosticOrigin = 'test-body' | 'import' | 'collection' | 'hook' | 'fixture-setup' | 'unknown';
export type DiagnosticKind = 'assertion' | 'test-failure' | 'setup' | 'protocol' | 'runner' | 'preflight';
export type DiagnosticLimits = {
  maxEntries: number;
  maxMessageBytes: number;
  maxStackFrames: number;
  maxStackBytes: number;
  maxTotalBytes: number;
  maxProtocolLineBytes: number;
  maxStderrBytes: number;
  redactionPatterns: string[];
};
export type DiagnosticPaths = { workspace: string; qaHome: string; fixtureRoots: string[] };
export type DiagnosticFailure = {
  test: DiagnosticTestId | null;
  origin: DiagnosticOrigin;
  error: unknown;
  location?: DiagnosticLocation | null;
  unavailableReason?: string;
};
export type NodeDiagnosticEvent = {
  type: 'test:fail';
  data: {
    file?: string;
    name?: string;
    line?: number;
    column?: number;
    details: { error?: unknown; diagnosticOrigin?: DiagnosticOrigin };
  };
};
export type InlineDiagnostic = {
  kind: DiagnosticKind;
  test: DiagnosticTestId | null;
  errorName?: string;
  errorCode?: string;
  message: string;
  location: DiagnosticLocation | null;
  stack: string[];
  redacted: boolean;
  truncated: boolean;
  unavailableReason?: string;
};
export type DiagnosticSummary = {
  totalEntries: number;
  retainedEntries: number;
  omittedEntries: number;
  truncated: boolean;
  redacted: boolean;
};
export type DiagnosticEnvironmentInput = {
  executable: string;
  runtimeVersion: string;
  adapter: string;
  isolation: string;
  configurationBytes: { flow: Uint8Array; testRuns: Uint8Array; projects: Uint8Array };
  tmpPath: string;
  privateRunTmp: boolean;
};
export type DiagnosticEnvironmentSummary = {
  executable: string;
  runtimeVersion: string;
  adapter: string;
  isolation: string;
  configurationFingerprints: { flow: string; testRuns: string; projects: string };
  tmpPathBytes: number;
  privateRunTmp: boolean;
};
export type DiagnosticRunFacts = {
  runId: string;
  outcome: string;
  failureKinds: string[];
  knownRed: DiagnosticTestId[];
  unexecuted: DiagnosticTestId[];
  unknown: DiagnosticTestId[];
  timeoutCount: number | null;
  timedOut: boolean;
  cleanup: unknown;
  evidence: string[];
};
export type DiagnosticAttachment = {
  diagnostics: InlineDiagnostic[];
  diagnosticSummary: DiagnosticSummary;
  environmentSummary: DiagnosticEnvironmentSummary;
};
export type DiagnosticReadState = {
  protocolBufferedBytes: number;
  stderrBufferedBytes: number;
  protocolRejected: boolean;
  stderrTruncated: boolean;
};
export type DiagnosticDisposition = { failureKind: 'assertions' | 'setup' | null; knownRed: DiagnosticTestId | null };

const configurationErrors = new WeakMap<object, string>();
export const rejectTestRunConfiguration = (message: string): never => {
  const error = Object.assign(new Error(message), { code: 'CONFIGURATION_INVALID' });
  configurationErrors.set(error, message);
  throw error;
};
const invalid = rejectTestRunConfiguration;
export function diagnosticConfigurationFailure(error: unknown): InlineDiagnostic | null {
  const message = error && typeof error === 'object' ? configurationErrors.get(error) : undefined;
  return message ? { kind: 'preflight', test: null, errorCode: 'CONFIGURATION_INVALID', message, location: null, stack: [], redacted: false, truncated: false, unavailableReason: 'Test run configuration was rejected before collection' } : null;
}
const object = (v: unknown): v is Record<string, any> => !!v && typeof v === 'object' && !Array.isArray(v);
const bytes = (s: string) => Buffer.byteLength(s);
const clip = (s: string, n: number): string => { let out = ''; let size = 0; for (const c of s) { size += bytes(c); if (size > n) break; out += c; } return out; };
const inside = (p: string, root: string) => p === root || p.startsWith(root + sep);
const nativeStackGetter = Object.getOwnPropertyDescriptor(new Error(), 'stack')?.get;
const safeStackLabels = (error: object): boolean => ['name', 'message'].every(key => {
  let current: object | null = error;
  while (current) {
    const descriptor = Object.getOwnPropertyDescriptor(current, key);
    if (descriptor) return 'value' in descriptor && (descriptor.value === undefined || typeof descriptor.value === 'string');
    current = Object.getPrototypeOf(current);
  }
  return true;
});
function safeError(error: unknown, seen = new Set<unknown>()): any {
  if (!object(error)) return typeof error === 'string' ? error : null;
  if (seen.has(error)) return null;
  seen.add(error);
  const out: Record<string, unknown> = {};
  try {
    for (const key of ['name', 'code', 'failureType', 'exitCode', 'signal', 'diagnosticOrigin', 'generatedMessage', 'operator', 'message', 'stack', 'cause']) {
      let current: object | null = error;
      while (current) {
        const descriptor = Object.getOwnPropertyDescriptor(current, key);
        if (descriptor) {
          if ('value' in descriptor) out[key] = key === 'cause' ? safeError(descriptor.value, seen) : descriptor.value;
          else if (key === 'stack' && nativeStackGetter && descriptor.get === nativeStackGetter && types.isNativeError(error) && safeStackLabels(error)) out.stack = nativeStackGetter.call(error);
          break;
        }
        current = Object.getPrototypeOf(current);
